// Effects, part 3: fear (c1-c4) and clash (d1-d6): cold light, the delayed blast, blows in six weights, rock, beams, steel letters.   Keys: D Phrygian, D minor.
import * as P from './sfx_phys.mjs';
const { def, CH, SR, TAU, N, St, noise, pink, brown, band, lp, hp, bp, lp4, hp4, svf, mul, mix, unit, unitr, bank, buf, pulse, poisson, slip, wander, clamp, lerp, smooth, thud, nb, grain, crumbs, rustle, bubbles, cloth, whoosh, whistle, strike, dense, flesh, squelch, fracture, lightning, fadeEnds, cluster, reversed, blast, nwave, rumble, groundwave, pebble, ring, wind, flame, ki, stream, arcs, gather, splash, drops, steelModes, groan, rock, grind, dust, body, flap, syll, glottis, formants, inside } = P;
