def('sea_black', { d: 'a black sea that barely breathes', hear: 'slow dark water', lv: -24, cat: 'amb', hi: 1800, fade: [.5, .2], def: { dur: 3.3 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const c of [0, 1]) { const x = band(r, n, 70, 700, pink), w = wander(r, n, .9); for (let i = 0; i < n; i++) { const t = i / SR; x[i] *= .4 + .6 * Math.pow(.5 + .5 * Math.sin(TAU * t / 2.4 + c), 2) + .15 * w[i]; } mix(c ? st.r : st.l, unitr(x, .2), .8); } for (const t of poisson(r, d, 2.2)) squelch(st, r, { at: t, dur: Math.max(.05, Math.min(.5, d - t)), f0: 130, f1: 520, q: 1.8, rate: 8, a: .3, pan: r.u(-.8, .8), gate: .6 }); return st; });
def('moon_presence', { d: 'a disc too large for the sky: two lows a semitone apart that grind slowly against each other, a bowed edge high above', hear: 'an ominous low beating drone', lv: -14, cat: 'amb', hi: 3600, fade: [1, .4], def: { dur: 3.3 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const [f, g, p] of [[D / 4, .5, -.1], [Eb / 4, .4, .1], [D / 2, .8, .3], [Eb / 2, .62, -.3], [D, .44, -.2], [Eb, .34, .25], [A, .16, 0], [D * 2, .1, .4], [Eb * 2, .08, -.4]]) { const x = new Float64Array(n), w = wander(r, n, .8); let ph = r() * TAU; for (let i = 0; i < n; i++) { ph += TAU * f * (1 + .002 * w[i]) / SR; x[i] = (Math.sin(ph) + .25 * Math.sin(2 * ph + 1)) * (.6 + .4 * w[i]) * smooth(i / n * 1.6); } st.add(x, { g: g * .34, pan: p }); } const x = slip(r, d, () => Eb * 4, { jit: .012, tc: .0006, amp: t => Math.pow(.5 + .5 * Math.sin(t * 1.9), 2) }); st.add(unit(bank(x, [[Eb * 4, .4, 1], [Eb * 8.1, .3, .3], [D * 4, .5, .5]], n)), { g: .07, pan: .2 }); return st; });
def('cloud_part', { d: 'black cloud slides off the disc', hear: 'a deep slow sliding air', sync: .8, lv: -15, hi: 1300, fade: [.4, .5], def: { dur: 2 } }, (o, r) => { const st = new St(o.dur); for (const [f, p] of [[170, -.6], [230, .6]]) whoosh(st, r, { dur: o.dur, f, q: .8, a: .7, u: x => Math.sin(Math.PI * Math.pow(x, .8)), pan: x => p * (.4 + .8 * x), hi: 900, pw: 1.6 }); return st; });
def('descend_hum', { d: 'something weightless comes down: a glassy pair of tones that never settle, air bending away from it', hear: 'a cold eerie descending hum', lv: -13, hi: 4200, fade: [.3, .3], def: { dur: 2 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const [f, g, df] of [[Eb * 2, 1, 3.1], [A * 2, .5, -2.3], [D * 4, .35, 5.2], [Eb * 8, .07, 7]]) for (const s of [-1, 1]) { const x = new Float64Array(n), w = wander(r, n, 2); let ph = 0; for (let i = 0; i < n; i++) { const u = i / n; ph += TAU * (f * Math.pow(2, -.13 * u) + df * s) / SR; x[i] = Math.sin(ph + .9 * Math.sin(ph * .5)) * Math.sin(Math.PI * Math.pow(u, .7)) * (.7 + .3 * w[i]); } st.add(x, { g: g * .12, pan: s * .6 }); } for (const c of [0, 1]) { const x = pink(r, n); svf(x, t => 420 - 180 * t / d, 2.4, 'bp'); for (let i = 0; i < n; i++) x[i] *= Math.sin(Math.PI * i / n); mix(c ? st.r : st.l, unit(x), .14); } return st; });
def('tail_uncoil', { d: 'a smooth heavy tail unwinds', hear: 'slow leathery stretching', sync: .3, lv: -14, hi: 2200 }, (o, r) => { const st = new St(1.3), x = slip(r, .9, t => 16 + 22 * Math.sin(Math.PI * t / .9), { jit: .4, tc: .004, amp: t => Math.sin(Math.PI * t / .9) }); st.add(unit(bank(x, [[130, .05, 1], [290, .04, .8], [520, .03, .5], [980, .02, .2]], N(1.1))), { g: .5 }); whoosh(st, r, { at: .1, dur: 1, f: 260, q: .9, a: .6, pan: x => -.4 + .8 * x, hi: 1100 }); return st; });
def('spark_hang', { d: 'violet sparks hang in the air, now and then one spits', hear: 'sparse tiny cold ticks', lv: -19, cat: 'amb', hi: 5200, fade: [.2, .2], def: { dur: 2.4, rate: 4 } }, (o, r) => { const st = new St(o.dur); for (const t of poisson(r, o.dur - .3, o.rate)) { const p = r.u(-1, 1), f = r.pick([Eb * 8, D * 8, A * 8, Eb * 16]); grain(st, r, t, r.log(1400, 3200), 1.4, 1.2, .5 * r.u(.3, 1), p); st.ping(t + .002, f, .2, .1 * r.u(.4, 1), p, 0, .002); } return st; });
def('eyes_red', { d: 'two eyes open in a black face: two embers drawn awake, and the floor drops', hear: 'a small wet click and an ominous low pulse', sync: .03, lv: -3, hi: 4600, cat: 'hit' }, (o, r) => { const st = new St(1.9), T = .03; for (const [dt, p] of [[0, -.22], [.028, .22]]) { grain(st, r, T + dt, 820, 1.2, 5, .7, p); nb(st, r, T + dt, 190, 700, .003, .05, .5, { pan: p, src: pink }); for (let k = 0; k < 4; k++) grain(st, r, T + dt + r() * .05, r.log(1200, 2600), 1.3, 1.2, .2, p); } thud(st, T, 74, 36.7, 1.3, 1.5, { glide: .22, atk: .02 }); thud(st, T + .01, 78, 38.9, 1.1, .9, { glide: .22, atk: .03 }); cluster(st, r, [[Eb * 4, .16, -.4, T, .05], [D * 4 * 1.003, .14, .4, T, .06], [A * 4, .05, 0, T + .1, .2]], { dur: 1.6, drift: .001, am: .2, rel: 1, rate: 3 }); return st; });
