def('ball_stone', { d: 'the ball strikes stone, heavy and dull in slowed time, then rolls', hear: 'a heavy glass ball dropping on stone and rolling', sync: .01, lv: -3, hi: 4200, cat: 'hit', def: { roll: .7 } }, (o, r) => { const st = new St(1.6), T = .01; P.ceramic(st, r, T, { f: .42, a: .6, ring: .2 }); rock(st, r, { at: T, size: 1, a: .5, dur: .1, crumb: 0 }); thud(st, T, 150, 64, .24, .9, { atk: .002 }); nb(st, r, T, 260, 1500, .0005, .05, 1, { src: pink }); if (o.roll) { const n = N(o.roll), x = band(r, n, 140, 1300, pink), w = wander(r, n, 20); for (let i = 0; i < n; i++) { const u = i / n; x[i] *= (.45 + .55 * Math.pow(Math.sin(TAU * 4.5 * u + .6), 2)) * (.7 + .3 * w[i]) * smooth(u / .12) * smooth((1 - u) / .1); } st.add(unit(x), { at: T + .14, g: .34 }); for (let t = T + .16; t < T + .14 + o.roll; t += r.u(.06, .11)) grain(st, r, t, r.log(500, 1300), .8, 2.5, .16 * r.u(.4, 1)); } return st; });
