def('blast_arrive', { d: 'the sound of a mountain range removed, arriving all at once, long after the light: front, ground bounce, fireball, cliffs answering, sky rolling', hear: 'a colossal explosion shockwave with a long rolling rumble', sync: .02, lv: 5, hi: 7200, lo: 24, cat: 'hit', fade: [.001, 1.2], def: { dur: 4.5 } }, (o, r) => {
  const st = new St(o.dur), T = .02; P.boom(st, r, T, { size: 5, a: 1.5, crack: 1.3, thump: 1.1, mid: 1.4, tail: 1, air_: .8, echo: 1.2 }); P.boom(st, r, T + .055, { size: 3, a: .7, crack: .4, thump: .8, mid: 1, tail: 0, air_: 0 }); lightning(st, r, { at: T, dur: .8, n: 300, crack: .06, wave: [.0005, .003], a: 1.1, fall: 4, claps: 5 }); P.crunch(st, r, T + .01, { f: 300, L: .8, a: 1.5, sharp: 1 }); P.crunch(st, r, T + .16, { f: 220, L: .7, a: .9, sharp: .3, pan: -.5 }); P.crunch(st, r, T + .34, { f: 260, L: .9, a: .8, sharp: .3, pan: .5 }); P.crunch(st, r, T + .62, { f: 180, L: 1, a: .6, sharp: .2, pan: -.2 });
  for (const s of [0, 1]) { const n = N(3), x = pink(r, n), w = wander(r, n, 5), w2 = wander(r, n, 14); svf(x, t => 260 + 1300 * Math.exp(-t * 2.2) + 160 * w[Math.min(n - 1, Math.floor(t * SR))], .6, 'bp'); for (let i = 0; i < n; i++) { const u = i / n; x[i] *= Math.min(1, i / 300) * Math.pow(1 - u, 1.6) * Math.max(0, .5 + .34 * w[i] + .16 * w2[i]); } mix(s ? st.r : st.l, unit(x), .5, T + .03); } rumble(st, r, { at: T + .08, dur: o.dur - .12, f0: 900, f1: 120, a: 1.1, humps: 12, atk: .03, fall: 2.2, lo: 40 }); return st;
});
