def('cape_shred', { d: 'the cape goes to ribbons: cloth ripped in runs, loose ends crack', hear: 'heavy cloth ripping and flapping in a gale', sync: 0, lv: -8, hi: 4200, lo: 160, fade: [.02, .2], def: { dur: .75 } }, (o, r) => { const d = o.dur, st = new St(d + .1); for (let k = 0; k < 4; k++) { const t0 = d * .7 * k / 4 + r.u(0, .05), L = r.u(.18, .3), p = r.u(-.6, .6), n = N(L), x = band(r, n, 500, 3600, pink), w = wander(r, n, 190), rp = wander(r, n, 60); for (let i = 0; i < n; i++) { const u = i / n; x[i] *= (.3 + .7 * Math.abs(w[i])) * (.7 + .3 * rp[i]) * Math.sin(Math.PI * Math.pow(u, .6)); } svf(x, t => 900 + 1500 * Math.pow(t / L, 1.4), .7, 'bp'); st.add(unit(x), { at: t0, g: .8, pan: p }); } flap(st, r, { dur: d, rate: 20, a: 1.1, shape: u => 1 - .4 * u, lo: 320, hi: 2200 }); return st; });
