def('claw_ink', { d: 'a printed hand claws out of the page: paper strains, ink cracks', hear: 'paper straining and a dry scrape', sync: .05, lv: -7, hi: 4600 }, (o, r) => { const st = new St(.8); for (let k = 0; k < 5; k++) { const n = N(.2), x = band(r, n, 500, 3200, noise), w = wander(r, n, 80); for (let i = 0; i < n; i++) x[i] *= Math.sin(Math.PI * i / n) * Math.pow(.5 + .5 * w[i], 2); st.add(unit(x), { at: .02 + k * .03, g: .22, pan: -.5 + .25 * k }); } rustle(st, r, { dur: .5, rate: 220, lo: 700, hi: 3200, a: .2, shape: u => 1 - u }); nb(st, r, .05, 120, 700, .004, .1, .7, { src: pink }); return st; });
def('palm_spark', { d: 'the only colour on the page: a spark in a proud hand that grows until it screams', hear: 'a bright electric energy growing in intensity', sync: 0, lv: -7, hi: 13000, fade: [.05, .02], def: { dur: 1.3 } }, (o, r) => { const d = o.dur, st = new St(d); P.core(st, r, 'vegeta', [A, A * 1.2, A * 1.5], { dur: d, a: 4.5, shape: u => .12 + .88 * u * u, pitch: u => 1 + .5 * u * u, move: 1.4 }); arcs(st, r, { dur: d, rate: 16, a: .7, shape: u => .25 + .75 * u * u, spread: .5 }); P.grit(st, r, { dur: d, a: .3, rate: 200, shape: u => u * u }); return st; });
def('letters_loom', { d: 'letters as tall as buildings stand in the wind: iron hum', hear: 'a deep metallic hum', sync: .0, lv: -11, cat: 'amb', hi: 1800, lo: 24, fade: [.3, .3], def: { dur: 1.7 } }, (o, r) => { const d = o.dur, st = new St(d), m = steelModes(r, { f: 36.7, n: 22, hi: 700, t60: 2 }); groan(st, r, m, { dur: d, rate: () => 9, a: .7, jit: .7, tc: .006 }); st.wide(() => unit(band(r, N(d), 40, 220, brown)), { g: .3 }); return st; });
def('beam_fire', { d: 'a beam leaves the hands: the sphere collapses forward, the air is thrown out of the line, and the power\'s own voice stands up in it', hear: 'a powerful energy beam blasting out with a singing core', sync: .05, lv: 4, hi: 14000, lo: 26, cat: 'hit', def: { who: 'goku' } }, (o, r) => { const st = new St(2), T = .05, c = CH(o); { const n = N(T); for (const s of [0, 1]) { const x = pink(r, n); for (let i = 0; i < n; i++) x[i] *= Math.pow(i / n, 2); mix(s ? st.r : st.l, unit(lp4(x, 5200)), .3); } } P.core(st, r, o.who, c, { at: 0, dur: T, a: .9, shape: u => u * u, pitch: u => 1.9 - .9 * u, move: 2 }); P.boom(st, r, T, { size: 2.2, a: 1, crack: 1.3, thump: 1, mid: 1.1, tail: .4, echo: .4 }); P.core(st, r, o.who, c, { at: T, dur: 1.7, a: 4.2, shape: u => Math.min(1, u * 60) * Math.pow(1 - u, .9), pitch: u => 1 + .35 * Math.exp(-u * 26) }); for (const p of [-.3, .8]) whoosh(st, r, { at: T + .02, dur: 1.2, f: 900, q: .9, a: .5, u: x => Math.pow(1 - x, 1.1) * Math.min(1, x * 12), hi: 5200, pan: x => -.5 + (p + .5) * x }); flame(st, r, { at: T, dur: 1.3, a: .45, size: 1.2, licks: 22, shape: u => Math.min(1, u * 40) * Math.pow(1 - u, 1.1), hi: 2600 }); arcs(st, r, { at: T, dur: .9, rate: 14, a: .6, shape: u => 1 - u }); P.grit(st, r, { at: T, dur: 1.2, a: .8, rate: 280 }); return st; });
def('beam_hold', { d: 'a held beam, mostly voice: its partials climb through one another, surges run down its length, plasma spits, the floor shakes.  who goku | vegeta | frieza | both', hear: 'a sustained singing energy beam with surges running through it', sync: 0, lv: 0, hi: 13000, lo: 26, cat: 'hit', fade: [.03, .08], def: { dur: 2, who: 'goku', dir: 1, grow: 0 } }, (o, r) => { const d = o.dur, st = new St(d), c = CH(o), sh = u => (o.grow ? .5 + .5 * u : 1), pt = u => 1 + (o.grow ? .07 * u : 0) + .005 * Math.sin(u * d * 21), W_ = o.who === 'both' ? ['goku', 'vegeta'] : [o.who];
  W_.forEach((w, i) => { const q = new St(d); P.core(q, r, w, c, { dur: d, a: w === 'frieza' ? 7 : 4.4, shape: sh, pitch: pt }); if (W_.length > 1) for (let k = 0; k < q.n; k++) { const an = TAU * 1.2 * k / SR + i * Math.PI, p = .7 * Math.sin(an), a = (p + 1) * Math.PI / 4, m = (q.l[k] + q.r[k]) * .5, s = (q.l[k] - q.r[k]) * .5; st.l[k] += (m * Math.cos(a) * 1.414 + s * .6) * (.8 + .2 * Math.cos(an)); st.r[k] += (m * Math.sin(a) * 1.414 - s * .6) * (.8 + .2 * Math.cos(an)); } else st.addSt(q); });
  for (let t = r.u(0, .06); t < d - .12; t += r.u(.15, .3)) { const L = Math.min(d - t, r.u(.28, .46)), g = r.u(.5, 1) * sh(t / d), f = r.log(340, 700) * (o.who === 'frieza' ? 1.8 : 1); whoosh(st, r, { at: t, dur: L, f, q: 1.4, a: .09 * g, u: x => Math.pow(Math.sin(Math.PI * Math.pow(x, .6)), 1.1), hi: 4200, pan: x => o.dir * (-.95 + 1.9 * x) }); }
  for (const s of [0, 1]) { const n = N(d), x = band(r, n, 30, 95, brown), w = wander(r, n, 14); for (let i = 0; i < n; i++) x[i] = Math.tanh(2 * x[i] * sh(i / n) * (.55 + .45 * w[i])); mix(s ? st.r : st.l, unitr(x, .2), o.who === 'frieza' ? .2 : .4); } if (o.who !== 'frieza') flame(st, r, { dur: d, a: .12, size: 1.6, licks: 6, hi: 2000, shape: sh }); arcs(st, r, { dur: d, rate: o.who === 'goku' ? 5 : 10, a: .5, shape: sh }); P.grit(st, r, { dur: d, a: .5, rate: 34, shape: sh }); return st; });
def('beam_inside', { d: 'standing inside somebody else\'s beam: its voice in both ears, pressure on the drums, light rushing by left and right', hear: 'a muffled singing roar all around', sync: 0, lv: -5, cat: 'amb', hi: 5200, lo: 26, fade: [.06, .06], def: { dur: 1.6, who: 'vegeta' } }, (o, r) => { const d = o.dur, st = new St(d), c = CH(o); const q = new St(d); P.core(q, r, o.who, c, { dur: d, a: 4, move: .8, width: 1 }); q.each(x => lp4(x, 2400)); st.addSt(q); for (const s of [0, 1]) { const n = N(d), x = pink(r, n), w = wander(r, n, 6), b = band(r, n, 34, 130, brown); svf(x, t => 420 + 200 * w[Math.min(n - 1, Math.floor(t * SR))], 1.2, 'bp'); for (let i = 0; i < n; i++) { x[i] *= .65 + .35 * w[i]; b[i] *= .6 + .4 * w[i]; } mix(s ? st.r : st.l, unitr(lp4(x, 1900), .2), .34); mix(s ? st.r : st.l, unitr(b, .2), .5); } for (const p of [-1, 1]) for (let t = r.u(0, .1); t < d - .2; t += r.u(.16, .3)) whoosh(st, r, { at: t, dur: .3, f: r.log(700, 1500), q: 1.5, a: .3, u: x => Math.sin(Math.PI * x), pan: x => p * (1 - .5 * x), hi: 4200 }); return st; });
def('beam_step', { d: 'one step against the flow: grit under a heel, the light giving way round a shin', hear: 'a heavy step on gritty rock with energy shearing past', sync: .05, lv: -1, hi: 5200, cat: 'hit' }, (o, r) => { const st = new St(.9), T = .05; thud(st, T, 130, 50, .3, 1.2, { glide: .04, atk: .003 }); P.crunch(st, r, T, { f: 620, L: .13, a: 1.2, sharp: 1 }); P.crunch(st, r, T + .045, { f: 900, L: .09, a: .5, sharp: .4 }); nb(st, r, T, 900, 3600, .0005, .03, .9); for (const p of [-.85, .85]) { whoosh(st, r, { at: T - .03, dur: .42, f: 1300, q: 1.3, a: .7, u: x => Math.pow(1 - x, 1.1) * Math.min(1, x * 7), pan: x => p * (.2 + .8 * x), hi: 4200 }); whoosh(st, r, { at: T - .03, dur: .42, f: 420, q: 1, a: .5, u: x => Math.pow(1 - x, 1.1) * Math.min(1, x * 7), pan: x => p * (.2 + .8 * x), hi: 1600 }); } arcs(st, r, { at: T, dur: .2, rate: 26, a: .4, shape: u => 1 - u }); return st; });
def('beam_parted', { d: 'one hand divides the beam: its voice splits left and right, a tone apart, and leaves a quiet slit in the middle', hear: 'a singing energy stream splitting to both sides', sync: .1, lv: -3, hi: 9000, lo: 60, cat: 'hit', fade: [.08, .12], def: { dur: 1.2, who: 'vegeta' } }, (o, r) => { const d = o.dur, st = new St(d); for (const p of [-1, 1]) { const q = new St(d); P.core(q, r, o.who, CH(o), { dur: d, a: 3.6, pitch: u => 1 + p * .03 * smooth(u * 3), width: .1, move: 1.5 }); for (let i = 0; i < q.n; i++) { const pn = p * Math.min(1, .2 + i / SR * 2.4), a = (pn + 1) * Math.PI / 4, m = (q.l[i] + q.r[i]) * .5; st.l[i] += m * Math.cos(a) * 1.414; st.r[i] += m * Math.sin(a) * 1.414; } for (let t = .02; t < d - .2; t += r.u(.12, .24)) whoosh(st, r, { at: t, dur: .34, f: r.log(600, 1300), q: 1.3, a: .4, u: x => Math.pow(1 - x, 1.1) * Math.min(1, x * 8), pan: x => p * (.2 + .8 * x), hi: 5200 }); } arcs(st, r, { dur: d, rate: 10, a: .5 }); P.grit(st, r, { dur: d, a: .3, rate: 160 }); return st; });
def('beam_die', { d: 'the beam runs out: its voice sinks and opens, the last sparks fall, the air comes back', hear: 'an energy tone sinking and dying with falling sparks', sync: .02, lv: -6, hi: 9000, fade: [.01, .2], def: { who: 'vegeta' } }, (o, r) => { const st = new St(1), c = CH(o); P.core(st, r, o.who, c, { dur: .75, a: 4, shape: u => Math.pow(1 - u, 1.7), pitch: u => Math.pow(2, -u * 1.1), move: .6 }); whoosh(st, r, { dur: .7, f: 700, q: .9, a: .4, u: x => Math.pow(1 - x, 1.2), hi: 2600 }); P.grit(st, r, { at: .05, dur: .8, a: .3, rate: 90, fall: 2.4 }); return st; });
