def('flick', { d: 'the finger lets go: nail, skin, the bone behind it, very close', hear: 'a sharp finger flick against a skull', sync: .006, lv: -1, hi: 6400, cat: 'hit' }, (o, r) => { const st = new St(.3), T = .006; nwave(st, T, { len: .0011, a: .8, rise: .00018 }); nb(st, r, T, 1300, 5200, .0002, .014, 1.3); grain(st, r, T, 1150, .9, 4, 1); P.crunch(st, r, T, { f: 700, L: .04, a: .9, sharp: 1 }); thud(st, T, 290, 150, .09, 1.2, { glide: .012, atk: .001, drive: 2 }); nb(st, r, T, 130, 480, .0008, .06, 1.1, { src: pink }); return st; });
def('armour_shatter', { d: 'a wave of breakage runs across composite armour: plates craze, let go and scatter', hear: 'thick hard armour plates smashing to pieces in a wave', sync: .02, lv: 3, hi: 5600, lo: 60, cat: 'hit', def: { dur: .55 } }, (o, r) => { const st = new St(2), T = .02, plate = (t, f, g, p, ring_) => { P.grit(st, r, { at: t, dur: .26, a: 1.1 * g, rate: 300, pan: p, spread: .3 }); strike(st, r, t, dense(r, { lo: 640 * f, hi: 9500, n: 38, t60: ring_, roll: .25, tilt: -.1, jit: 1 }), { tc: .0005, rough: 2.4, rt: .004, a: .8 * g, pan: p, dur: ring_ * 1.4 + .03, width: .5, hits: [[0, 1], [r.u(.005, .012), .5]] }); P.crunch(st, r, t, { f: 1100 * f, L: .06, a: .8 * g, pan: p, sharp: 1 }); }; blast(st, T, { tp: .014, a: 1, rise: .0008 }); thud(st, T, 150, 54, .3, .9, { glide: .04 }); P.crunch(st, r, T, { f: 420, L: .26, a: 1.6, sharp: 1 }); for (let k = 0; k < 9; k++) { const u = k / 8, t = T + o.dur * Math.pow(u, .8), p = clamp(-.7 + 1.4 * u + r.u(-.15, .15), -1, 1), g = (1 - .5 * u) * r.u(.7, 1); plate(t, r.u(.8, 1.5), g, p, .09); nb(st, r, t, 140, 560, .0012, .1, .9 * g, { pan: p, src: pink }); } for (let k = 0; k < 13; k++) { const t = T + .3 + 1.2 * Math.pow(r(), 1.2); plate(t, r.u(1.2, 2.2), .32 * r.u(.3, 1) * (1 - t / 2.2), r.u(-.9, .9), .06); } return st; });
def('gone', { d: 'a man leaves the frame faster than the ear: double crack, a tunnel of air falling in behind', hear: 'a supersonic exit with a double crack', sync: .02, lv: 1, hi: 4600, lo: 24, cat: 'hit' }, (o, r) => { const st = new St(1.3), T = .02, dir = o.dir ?? 1; nwave(st, T, { len: .009, a: .9, rise: .0005 }); nwave(st, T + .02, { len: .012, a: .6, rise: .0007, pan: .4 * dir }); thud(st, T, 110, 40, .4, 1.2); whoosh(st, r, { at: T, dur: .9, f: 1200, q: .9, a: .9, u: x => Math.pow(1 - x, 1.1) * Math.min(1, x * 20), pan: x => dir * Math.min(1, x * 1.6), hi: 3800 }); return st; });
def('trench', { d: 'a furrow is ploughed to the horizon: rock thrown up faster than it can fall, going away', hear: 'a trench of rock ploughing away into the distance', sync: 0, lv: 0, hi: 3800, lo: 24, cat: 'hit', fade: [.02, .4], def: { dur: 1.3, dir: 1 } }, (o, r) => { const d = o.dur, q = new St(d + .4); for (let t = 0, k = 0; t < d; k++) { const u = t / d; rock(q, r, { at: t, size: 1.6 - .6 * u, a: (1 - .72 * u) * r.u(.6, 1), pan: clamp(o.dir * (u * 1.2 - .1) + r.u(-.15, .15), -1, 1), dur: .4, crumb: .6 }); t += .07 + .05 * u; } rumble(q, r, { dur: d + .3, f0: 420, f1: 60, a: .6, humps: 8 }); dust(q, r, { at: .05, dur: d, a: .5, pan: .4 * o.dir }); for (const c of [q.l, q.r]) svf(c, t => 4200 * Math.exp(-t * 1.4) + 380, .7, 'lp'); st_fade(q, .25); return q; });
function st_fade(st, t) { fadeEnds(st.l, .001, t); fadeEnds(st.r, .001, t); return st; }
def('breath_hard', { d: 'ragged breath of a beaten man', hear: 'heavy exhausted breathing', sync: .1, lv: -12, hi: 3800, fade: [.03, .08], def: { n: 2, gap: .55, f: 1 } }, (o, r) => { const st = new St(o.n * o.gap * 2 + .4); let t = 0; for (let k = 0; k < o.n; k++) { for (const [dt, L, f, g] of [[0, .3, 1150, .5], [.36, .42, 720, .9]]) { const n = N(L), x = band(r, n, 220, 3000, pink), w = wander(r, n, 30), y = new Float64Array(n); for (const [q, b, a] of [[f * .62 * o.f, 5, 1], [f * 1.45 * o.f, 6, .6], [f * 2.4 * o.f, 7, .25]]) mix(y, svf(Float64Array.from(x), q, b, 'bp'), a); for (let i = 0; i < n; i++) { const u = i / n; y[i] *= Math.pow(Math.sin(Math.PI * Math.pow(u, .6)), 1.2) * (.75 + .25 * w[i]); } st.add(unit(y), { at: t + dt, g: g * .7 }); } t += o.gap * 1.5; } return st; });
def('time_slow', { d: 'the world runs down: everything drops an octave and stretches', hear: 'time slowing down, a pitch falling', sync: .0, lv: -7, hi: 2800, fade: [.03, .3], def: { dur: 1 } }, (o, r) => { const d = o.dur, st = new St(d), n = N(d); for (const [f, g] of [[D * 2, .3], [A, .3], [D, .4]]) { const x = new Float64Array(n); let ph = 0; for (let i = 0; i < n; i++) { const u = i / n; ph += TAU * f * Math.pow(2, -1.4 * smooth(u)) / SR; x[i] = (Math.sin(ph) + .3 * Math.sin(2 * ph)) * Math.pow(1 - u, .8) * smooth(u / .06); } st.add(x, { g: g * .5 }); } for (const c of [0, 1]) { const x = pink(r, n); svf(x, t => 1300 * Math.exp(-t * 3.2 / d) + 110, 1.1, 'bp'); for (let i = 0; i < n; i++) x[i] *= Math.pow(1 - i / n, 1.1); mix(c ? st.r : st.l, unit(x), .4); } return st; });
def('dash_slow', { d: 'a man already moving before his eyes know it, heard in slowed time', hear: 'a low slow powerful rush', sync: .4, lv: -8, hi: 1900, fade: [.1, .1], def: { dur: .7 } }, (o, r) => { const st = new St(o.dur); whoosh(st, r, { dur: o.dur, f: 260, q: .9, a: 1, u: x => Math.pow(x, 1.2) * (x < .96 ? 1 : 0), hi: 1300, pan: x => -.6 + .7 * x }); for (let k = 0; k < 3; k++) { thud(st, .1 + k * .2, 80, 42, .16, .6, { atk: .01 }); } return st; });
def('steel_crack', { d: 'a weld as thick as a man lets go in a standing steel letter: a shock that runs up the plate, rivets letting go one after another, a ring that will not stop', hear: 'a gigantic steel structure snapping, clang, popping rivets and long deep ring', sync: .012, lv: 2, hi: 7200, lo: 30, cat: 'hit', def: { dur: 2.4 } }, (o, r) => { const st = new St(o.dur), T = .012, D_ = o.dur - .05, mk = (lo, hi, n, t0, roll, tilt) => { const m = []; for (let i = 0; i < n; i++) { const f = lo * Math.pow(hi / lo, Math.pow(i / (n - 1), .9)) * r.u(.97, 1.03); m.push([f, t0 * Math.pow(lo / f, roll) * r.u(.5, 1.3), Math.pow(f / lo, tilt) * r.u(.25, 1) * r.sgn()]); } return m; };
  P.boom(st, r, T, { size: 1.6, a: .8, crack: 1.4, thump: .9, mid: .9, tail: .4, air_: 0, echo: .9 }); strike(st, r, T, mk(96, 4600, 84, 1.7, .32, -.1), { tc: .0005, rough: 2.4, rt: .005, a: 1.2, hits: [[0, 1], [.021, .6], [.052, .45], [.13, .3]], width: .8, dur: D_ }); strike(st, r, T, [[37, 2.6, .8], [58, 2.2, 1], [83, 1.8, .9], [121, 1.5, .8], [149, 1.3, .6], [186, 1.1, .6]], { tc: .006, rough: .3, a: .8, dur: D_ }); let t = T + .06, gap = .05; for (let k = 0; k < 9 && t < o.dur - .2; k++) { const p = (k % 2 ? 1 : -1) * r.u(.1, .7), g = .6 * Math.pow(.86, k); nwave(st, t, { len: .0009, a: .6 * g, rise: .00016, pan: p }); strike(st, r, t, mk(1300, 6000, 18, .06, .2, 0), { tc: .0004, rough: 1.8, a: .7 * g, pan: p, dur: .1 }); nb(st, r, t, 260, 1100, .0006, .06, .7 * g, { pan: p, src: pink }); t += gap * r.u(.7, 1.5); gap *= 1.18; } return st; });
def('steel_tip', { d: 'the cracked letter leans: girders twist, plates slide over bolts, thousands of tons wail lower and lower', hear: 'a colossal metal structure groaning and twisting as it leans', sync: 0, lv: 0, hi: 5200, lo: 28, cat: 'hit', fade: [.15, .006], def: { dur: .9 } }, (o, r) => { const d = o.dur, st = new St(d), m = steelModes(r, { f: 52, n: 70, hi: 3600, t60: .9, tilt: -.12, roll: .35 }); groan(st, r, m, { dur: d, rate: u => 17 - 6 * u + 8 * u * u, a: 1, shape: u => .25 + .75 * u, tc: .0012, width: .9, knock: .5 }); groan(st, r, steelModes(r, { f: 190, n: 50, hi: 4200, t60: .4, tilt: 0, roll: .3 }), { at: d * .12, dur: d * .88, rate: u => 33 - 12 * u, a: .6, shape: u => u, tc: .0007, knock: .2, pan: .4 }); groan(st, r, m.slice(0, 30), { dur: d, rate: u => 7 + 3 * u, a: .8, shape: u => u, tc: .004, knock: .9, pan: -.3 }); for (const c of [0, 1]) { const n = N(d), x = band(r, n, 32, 150, brown), w = wander(r, n, 6); for (let i = 0; i < n; i++) x[i] = Math.tanh(2.4 * x[i] * (i / n) * (.6 + .4 * w[i])); mix(c ? st.r : st.l, unitr(x, .2), 1.1); } for (const t of poisson(r, d, t => 4 + 12 * t / d)) { const p = r.u(-.8, .8), g = r.u(.2, .6) * (.3 + t / d); nwave(st, t, { len: .0009, a: .5 * g, rise: .0002, pan: p }); P.crunch(st, r, t, { f: r.log(500, 1200), L: .06, a: g, pan: p, sharp: .8 }); } return st; });
def('steel_fall', { d: 'a steel letter the size of a ship goes down', hear: 'a colossal metal structure crashing to the ground', sync: .06, lv: 3, hi: 4400, lo: 24, cat: 'hit', fade: [.01, .8], def: { dur: 3.4 } }, (o, r) => { const st = new St(o.dur), T = .06, m = steelModes(r, { f: 27, n: 80, hi: 2600, t60: 2.8 }); blast(st, T, { tp: .05, a: .9, rise: .003 }); thud(st, T, 88, 30, 1, 2, { glide: .1 }); strike(st, r, T, m.map(([f, t, a]) => [f, t, a * Math.pow(f / 120, .6)]), { tc: .0016, rough: 2, a: 1, hits: [[0, 1], [.09, .7], [.21, .5], [.38, .35], [.61, .2]], width: .9, dur: 3 }); rock(st, r, { at: T + .02, size: 2.4, a: 1, dur: 1.2 }); nb(st, r, T, 220, 2000, .001, .2, 1.1, { wide: .5 }); groan(st, r, m.slice(10, 40), { at: T + .3, dur: 1.6, rate: u => 34 - 22 * u, a: .4, shape: u => 1 - u }); dust(st, r, { at: T + .1, dur: 2.4, a: .5 }); return st; });
