def('line_pass', { d: 'the violet line passes through: glass drawn across glass, air and cloth seared on either side, everything behind it missing', hear: 'a thin cold glassy slice with a vacuum thump', sync: .02, lv: -1, hi: 12000, cat: 'hit', fade: [.002, .1], def: { dur: .45 } }, (o, r) => { const d = o.dur, st = new St(d), T = .02; nwave(st, T, { len: .0010, a: 1, rise: .00014 }); P.core(st, r, 'frieza', [D, Eb, A], { at: T, dur: d - T, a: 6, shape: u => Math.min(1, u * 80) * Math.pow(1 - u, 2), pitch: u => 1 + .12 * Math.exp(-u * 14), move: 2 }); { const m = N(.26), x = band(r, m, 1400, 9000, pink), w = wander(r, m, 130), w2 = wander(r, m, 33); for (let i = 0; i < m; i++) { const u = i / m; x[i] *= Math.min(1, i / 60) * Math.pow(1 - u, 2) * (.4 + .6 * Math.abs(w[i])) * (.7 + .3 * w2[i]); } st.add(unit(x), { at: T, g: .45 }); } nb(st, r, T, 70, 320, .0015, .16, 1.6, { src: pink }); thud(st, T, 120, 42, .3, 1.1, { atk: .002 }); whoosh(st, r, { at: T, dur: .4, f: 620, q: 1.4, a: .4, u: x => Math.pow(1 - x, 1.4), hi: 2200 }); P.grit(st, r, { at: T, dur: .3, a: .3, rate: 220 }); return st; });
